package com.dy.artisan3d.data.model.artisan.aboutimport kotlinx.serialization.SerialNameimport kotlinx.serialization.Serializable@Serializabledata class PublicationDto(    val id: Int? = null,    val date: String? = null,    val page: String? = null,    val link: String? = null,    @SerialName("pub_image") val pubImage: String? = null,    val translations: Map<String, PublicationTranslationDto>? = null)